from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]

workflows = {
'game-jam-24h.md': {
 'title':'24-Hour Game-Jam Operating Workflow','hours':24,'reserve':25,
 'schedule':[
 ('00:00–01:00','Resolve rules, brief, unique hook, platform, time and rights constraints.'),
 ('01:00–02:00','Define core loop, cut-lines, art bible, risk list and proof-set needs.'),
 ('02:00–05:30','Build a complete playable prototype with one representative challenge and restart.'),
 ('05:30–08:30','Generate/refine and approve the smallest coherent set: focal character/object, environment, props and UI.'),
 ('08:30–13:30','Integrate gameplay, level, art, animations, effects, sound and menus.'),
 ('13:30–16:30','Content freeze; test core loop and repair the most consequential visual/gameplay defects.'),
 ('16:30–20:00','Polish feedback, accessibility basics, performance and error recovery.'),
 ('20:00–24:00','Build and launch exact export, regression, package, attribution, screenshots/logs/hash, submission.') ]},
'game-jam-72h.md': {
 'title':'72-Hour Game-Jam Operating Workflow','hours':72,'reserve':22,
 'schedule':[
 ('Hour 0–3','Brief, rules, constraints, differentiator, risks and bounded research.'),
 ('Hour 3–6','Core loop, design contract, art bible, dependency map and asset proof set.'),
 ('Hour 6–15','Complete playable vertical slice; test controls, one challenge, fail/success, restart.'),
 ('Hour 15–24','Lock visual direction; approve character/environment/props/UI/audio samples together.'),
 ('Hour 24–43','Create core content sequentially; implement levels, enemies/systems, interactions and progression.'),
 ('Hour 43–52','Integrate animation, VFX, interface, sound, transitions, and remaining critical content.'),
 ('Hour 52–59','Content freeze; blind playtest; fix blocking and high-impact readability failures.'),
 ('Hour 59–66','Balance, visual polish, regression, target export and real browser/desktop test.'),
 ('Hour 66–72','Release reserve, final artifact and license audit, hashes, documentation, submission.') ]},
'game-jam-14d.md': {
 'title':'14-Day Game-Jam / Production Sprint Workflow','hours':336,'reserve':20,
 'schedule':[
 ('Day 1','Brief, rules, concise research, player fantasy, success criteria and risks.'),
 ('Day 2','GDD, game-state model, level route, art bible, architecture, content schema.'),
 ('Days 3–4','Prototype risky systems; test visual model/workflow and one meaningful animation.'),
 ('Day 5','Playable vertical slice, first cold playtest, scope/architecture review.'),
 ('Days 6–8','Core gameplay and level systems; controlled content production with reference/style approvals.'),
 ('Days 9–10','Animation set, enemies/encounters, UI, audio and effects integrated.'),
 ('Day 11','Content complete; scenario coverage; identify defects and visual inconsistencies.'),
 ('Day 12','Content freeze, structured playtest, balance, accessibility and performance review.'),
 ('Day 13','Regression, target exports, cold playtest, provenance/license/package audit.'),
 ('Day 14','Release candidate, final blockers, packaging, submission and postmortem.') ]}}
for name,d in workflows.items():
    profile='24h' if d['hours']==24 else '72h' if d['hours']==72 else '14d'
    schedule='\n'.join(f'- **{time} — {task}**' for time,task in d['schedule'])
    body=f'''# {d['title']}\n\n## Purpose and boundary\nThis profile allocates **{d['hours']} elapsed hours**, not guaranteed productive capacity. Keep approximately **{d['reserve']}%** as release reserve for integration failures, engine/export issues, and submission requirements. Use `ags jam plan --profile {profile}` with real task estimates to produce a task shortlist; the calendar below is an operating rhythm, not a rigid promise.\n\n## Non-negotiable rules\n- Confirm jam rules, permitted AI/tool use, platform, deadline, attribution, and submission format before implementation.\n- Preserve a recoverable source state and working build throughout the sprint.\n- Define one distinctive player experience and one smallest compelling loop.\n- Produce a small cross-discipline visual proof set before mass asset generation. Review hero, environment, props, interface, and effects together.\n- Queue memory-heavy image generation sequentially when VRAM headroom is narrow. Record actual latencies and failures.\n- Separate generated candidate, technically valid file, integrated asset, in-engine verified asset, and human-approved asset.\n- Use actual player and build evidence. A test harness or export exit code does not prove game feel or art quality.\n- If scope slips, cut optional content before consuming the release reserve.\n\n## Suggested schedule\n{schedule}\n\n## Quality gates\n1. **Brief/compliance:** constraints and acceptance tests recorded.\n2. **Design/scope:** core loop, states, creative thesis, art bible, risks, and cut lines recorded.\n3. **Vertical slice:** the player can perform the core action, receive feedback, and reach a state transition in-engine.\n4. **Art proof:** representative character, environment, prop, UI, audio/effect choices fit a coherent style.\n5. **Content freeze:** required content is integrated; new features stop unless they resolve a release blocker.\n6. **Release candidate:** exact export is launched and core paths, restart, controls, and error recovery are tested.\n7. **Submission:** package requirements, attributions, manifests, hashes and human-gate status verified.\n\n## Scope cut order\nCut optional modes first; then secondary enemy variants; extra levels; cosmetics; nonessential narrative branches; expensive optional effects. Do not cut a completable core loop, essential controls, objective feedback, recovery/restart, required attribution, a real launch test, or mandatory submission artifacts.\n\n## Evidence required\nRetain the brief, art bible, task plan, asset/model provenance, rejected candidates, test logs with exit codes, actual build and SHA-256, screenshots or recordings from the running game, open defects, and human review decisions.\n\n## Stop rule\nStop generating new assets when the approved minimum set is integrated or when review/integration threatens test and release time. A queue of generated images is not a finished content set.\n'''
    (ROOT/'docs'/'workflows'/name).write_text(body,encoding='utf-8')

